def tit_for_tat(my_history, opp_history):
    return "C" if not opp_history else opp_history[-1]

def generous_tft(my_history, opp_history, forgiveness=0.1, rng=None):
    # retaliate, but forgive a defection with small probability - which breaks the
    # echo two strict retaliators fall into after a single mistake
    if opp_history and opp_history[-1] == "D":
        return "C" if rng.random() < forgiveness else "D"
    return "C"

def tit_for_two_tats(my_history, opp_history):
    # requires TWO consecutive defections before retaliating, so an isolated error is
    # absorbed rather than amplified
    return "D" if opp_history[-2:] == ["D", "D"] else "C"
